#!/usr/bin/env node
/* SPDX-License-Identifier: Apache-2.0 */
/**
 * Headless tests for pan-tsf-triage.html using system Chrome + playwright-core.
 * Uses only the synthetic bundles generated by scripts/generate_samples.py.
 */
import { chromium } from "playwright-core";
import http from "node:http";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const PORT = Number(process.env.PORT || 18765 + Math.floor(Math.random() * 1000));
const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript",
  ".css": "text/css",
  ".tgz": "application/gzip",
  ".gz": "application/gzip",
  ".png": "image/png",
  ".md": "text/markdown",
};

function startServer() {
  const server = http.createServer((req, res) => {
    const rel = decodeURIComponent((req.url || "/").split("?")[0]);
    let fp = path.join(ROOT, rel === "/" ? "pan-tsf-triage.html" : rel);
    if (!fp.startsWith(ROOT)) { res.writeHead(403); res.end(); return; }
    if (!fs.existsSync(fp) || fs.statSync(fp).isDirectory()) { res.writeHead(404); res.end("not found"); return; }
    const ext = path.extname(fp);
    res.writeHead(200, { "Content-Type": MIME[ext] || "application/octet-stream" });
    fs.createReadStream(fp).pipe(res);
  });
  return new Promise((resolve) => server.listen(PORT, "127.0.0.1", () => resolve(server)));
}

const chrome =
  process.env.CHROME_PATH ||
  ["/usr/bin/google-chrome-stable", "/usr/bin/google-chrome", "/usr/bin/chromium"].find((p) => fs.existsSync(p));

let failed = 0;
function assert(cond, msg) {
  if (!cond) {
    failed++;
    console.error("  FAIL:", msg);
  } else {
    console.log("  ok  :", msg);
  }
}

async function loadTsf(page, filePath, opts = {}) {
  const timeout = opts.timeout || 300000;
  const errors = [];
  page.on("pageerror", (e) => errors.push(String(e)));
  page.on("console", (msg) => {
    if (msg.type() === "error") {
      const tx = msg.text();
      if (/404|favicon/i.test(tx)) return;
      errors.push("console.error: " + tx);
    }
  });
  if (opts.observe || opts.budget) {
    await page.addInitScript(({ budget, observe }) => {
      if (budget) window.__TSF_BUDGET = budget;
      if (!observe) return;
      window.__longTasks = [];
      window.__maxHeap = 0;
      const rec = () => {
        try {
          if (performance.memory && performance.memory.usedJSHeapSize > window.__maxHeap) {
            window.__maxHeap = performance.memory.usedJSHeapSize;
          }
        } catch (e) {}
      };
      rec();
      setInterval(rec, 200);
      try {
        const po = new PerformanceObserver((list) => {
          for (const e of list.getEntries()) {
            window.__longTasks.push({ duration: e.duration, start: e.startTime });
          }
        });
        po.observe({ entryTypes: ["longtask"] });
      } catch (e) {
        window.__longTaskError = String(e);
      }
    }, { budget: opts.budget || 0, observe: !!opts.observe });
  }
  await page.goto(`http://127.0.0.1:${PORT}/pan-tsf-triage.html`, { waitUntil: "load" });
  await page.waitForFunction(() => window.__TSF && typeof window.__TSF.loadFiles === "function");
  const input = page.locator("#fi");
  await input.setInputFiles(filePath);
  await page.waitForFunction(() => window.__TSF && window.__TSF.ready === true, null, { timeout });
  const report = await page.evaluate(() => window.__TSF.getReport());
  const metrics = opts.observe
    ? await page.evaluate(() => ({
        longTasks: window.__longTasks || [],
        maxHeap: window.__maxHeap || 0,
        longTaskError: window.__longTaskError || null,
      }))
    : null;
  return { report, errors, metrics };
}

function titles(report) {
  return report.findings.map((f) => f.title);
}
function hasTitle(report, re) {
  return report.findings.some((f) => re.test(f.title));
}

function barCmd(cmd) {
  const bar = "=".repeat(80);
  return `\n${bar}\n== ${cmd}\n${bar}\n\n`;
}

function licenseCaseCli(opts = {}) {
  const wfVer = opts.wildfireVersion ?? "0";
  const wfDateLine = opts.wildfireDate ? `wildfire-release-date: ${opts.wildfireDate}\n` : "";
  const extraVersions = opts.extraVersions || `wf-private-version: 0
global-protect-datafile-version: 0
`;
  const includeLicenses = opts.licenses !== false;
  const licenseBody = opts.licenseBody || "";
  return [
    "Palo Alto Networks tech support (SYNTHETIC TEST DATA — not a live device)\n",
    barCmd("show system info"),
    `hostname: fw-example-lic
ip-address: 192.0.2.99
netmask: 255.255.255.0
default-gateway: 192.0.2.1
time: Mon Nov 10 12:00:00 2026
uptime: 10 days, 1:00:00
family: 400
model: PA-440
serial: 012345678999
sw-version: 11.1.4
app-version: 8990-9100
app-release-date: 2026/11/08 16:00:00 PDT
av-version: 4920-5510
av-release-date: 2026/11/08 16:00:00 PDT
threat-version: 8990-9100
threat-release-date: 2026/11/08 16:00:00 PDT
wildfire-version: ${wfVer}
${wfDateLine}url-filtering-version: 20261108.40111
url-filtering-release-date: 2026/11/08 00:00:00 PDT
${extraVersions}platform-family: 400
operational-mode: normal
system-mode: normal
`,
    includeLicenses ? barCmd("request license info") + licenseBody + "\n" : "",
  ].join("");
}

const LIC_THREAT_URL = `License entry:
Feature: Threat Prevention
Expires: November 10, 2028
Expired: No

License entry:
Feature: PAN-DB URL Filtering
Expires: November 10, 2028
Expired: No
`;

const LIC_WF_ACTIVE = `License entry:
Feature: WildFire License
Expires: November 10, 2028
Expired: No
`;

const LIC_WF_EXPIRED = `License entry:
Feature: WildFire License
Expires: October 01, 2026
Expired: Yes
`;

function writeMiniTsf(name, cliText) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tsf-lic-"));
  const folder = `techsupport_${name}_20261110_120000`;
  const cliDir = path.join(dir, folder, "tmp", "cli");
  fs.mkdirSync(cliDir, { recursive: true });
  fs.writeFileSync(path.join(cliDir, `techsupport_${folder}.txt`), cliText);
  const tgz = path.join(dir, `${name}.tgz`);
  const tar = spawnSync("tar", ["-czf", tgz, "-C", dir, folder], { encoding: "utf8" });
  if (tar.status !== 0) throw new Error("tar failed for " + name + ": " + (tar.stderr || tar.stdout));
  return tgz;
}

function finding(report, re) {
  return (report.findings || []).find((f) => re.test(f.title));
}

async function main() {
  const server = await startServer();
  const browser = await chromium.launch({
    executablePath: chrome,
    args: ["--no-sandbox", "--disable-dev-shm-usage"],
    headless: true,
  });
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });

  // ---- 1. firewall issues ----
  console.log("\n== synthetic firewall issues ==");
  const issuesPath = path.join(ROOT, "samples/techsupport_fw-issues.tgz");
  let { report, errors } = await loadTsf(page, issuesPath);
  assert(errors.length === 0, "no JS errors on fw-issues (" + errors.join(" | ") + ")");
  assert(report.type === "Firewall", "device type Firewall, got " + report.type);
  assert(report.device["Model"] === "PA-440", "model PA-440, got " + report.device["Model"]);
  assert(report.device["PAN-OS"] === "11.1.4", "PAN-OS 11.1.4, got " + report.device["PAN-OS"]);
  assert(report.device["Hostname"] === "fw-example", "hostname fw-example");
  assert(report.health < 70, "health is in the problem range, got " + report.health);
  const expectRe = [
    [/management-?plane CPU/i, "MP CPU"],
    [/dataplane CPU/i, "DP CPU"],
    [/memory utilization/i, "memory"],
    [/session table/i, "session table"],
    [/packet buffer|descriptor pool/i, "pools"],
    [/allocation failure/i, "alloc failures"],
    [/split brain/i, "split brain"],
    [/link monitoring/i, "HA link"],
    [/path monitoring/i, "HA path"],
    [/out of sync/i, "HA sync"],
    [/preempt/i, "HA preempt"],
    [/license expired/i, "expired license"],
    [/license expiring soon/i, "expiring license"],
    [/disk usage high/i, "disk"],
    [/commit job failed/i, "commit fail"],
    [/user-id/i, "userid"],
    [/authentication failure/i, "authd"],
    [/bgp/i, "bgp"],
    [/interface errors/i, "iface errors"],
    [/certificate expired|ssl decryption/i, "ssl/cert"],
    [/not connected to panorama|log forwarding/i, "panorama conn"],
    [/crash dump/i, "cores"],
    [/process restart/i, "restarts"],
    [/logging at session start/i, "log-start"],
    [/decryption rule looks very broad/i, "broad decrypt"],
    [/zone protection/i, "zpp"],
    [/unknown-tcp|unknown app-id/i, "unknown app"],
    [/tcp session timeout/i, "timeout"],
    [/jumbo frames/i, "jumbo"],
    [/zero hits/i, "unused rules"],
    [/ntp is not synchronized/i, "ntp"],
    [/content looks stale|looks stale/i, "stale content"],
  ];
  for (const [re, label] of expectRe) {
    assert(hasTitle(report, re), "finding present: " + label);
  }

  // click first finding -> logs tab, highlighted rows
  await page.locator("#topfindings .issue").first().click();
  await page.waitForTimeout(300);
  const onLogs = await page.evaluate(() => !document.querySelector("#tab-logs").hidden);
  assert(onLogs, "clicking a finding opens the Logs tab");
  const hits = await page.locator("#log .row.hit").count();
  assert(hits >= 1, "at least one highlighted evidence line, got " + hits);
  await page.evaluate(() => window.__TSF.showTab("findings"));
  await page.waitForTimeout(150);
  const findingsText = await page.locator("#issues").innerText();
  assert(findingsText.includes("running-config.xml"), "redaction does not treat running-config.xml as a hostname");
  assert(!/sslmgr\.\[HOST\]/.test(findingsText), "redaction does not treat sslmgr.log as a hostname");
  if (/sslmgr/.test(findingsText)) {
    assert(findingsText.includes("sslmgr.log"), "sslmgr.log remains visible in a finding source");
  }

  // regex search (clear any issue-line filter first)
  await page.evaluate(() => { window.__TSF.showTab("logs"); });
  const showAll = page.getByRole("button", { name: "Show all lines" });
  if (await showAll.count()) await showAll.click();
  await page.locator("#qre").check();
  await page.fill("#q", "Authentication failed|split-brain");
  await page.waitForTimeout(200);
  const shown = await page.locator("#log .row").count();
  assert(shown >= 1, "regex filter shows matching lines, got " + shown);

  // export with redaction
  const [download] = await Promise.all([
    page.waitForEvent("download"),
    page.click("#btn-csv"),
  ]);
  const csvPath = path.join(ROOT, "tests/_out.csv");
  await download.saveAs(csvPath);
  const csv = fs.readFileSync(csvPath, "utf8");
  assert(/critical/i.test(csv), "CSV contains findings");
  assert(!csv.includes("012345678901"), "CSV redacts serial");
  assert(!csv.includes("192.0.2.10"), "CSV redacts management IP");
  assert(!csv.includes("fw-example") || csv.includes("[HOSTNAME]"), "CSV redacts or tokenizes hostname");

  const [dl2] = await Promise.all([
    page.waitForEvent("download"),
    page.click("#btn-html"),
  ]);
  const htmlPath = path.join(ROOT, "tests/_out.html");
  await dl2.saveAs(htmlPath);
  const html = fs.readFileSync(htmlPath, "utf8");
  assert(html.includes("Health score"), "HTML report has health score");
  assert(!html.includes("012345678901"), "HTML report redacts serial");

  // identity hidden by default (Show sensitive values is off)
  const hostShown = await page.locator("#sum").innerText();
  assert(/Hidden — turn on Show sensitive values/.test(hostShown), "dashboard hides identity by default");
  assert(!hostShown.includes("fw-example"), "dashboard does not show hostname when hidden");
  assert(!hostShown.includes("012345678901"), "dashboard does not show serial when hidden");
  assert(/Source:\s*show system info/.test(hostShown), "identity source is shown even while hidden");
  assert(report.deviceSources && /show system info/i.test(report.deviceSources["Hostname"] || ""), "getReport hostname source is show system info");
  await page.locator("#showsens").check();
  await page.waitForTimeout(200);
  const shownSens = await page.locator("#sum").innerText();
  assert(shownSens.includes("fw-example"), "hostname appears when Show sensitive values is on");
  assert(shownSens.includes("012345678901"), "serial appears when Show sensitive values is on");
  await page.locator("#showsens").uncheck();
  await page.waitForTimeout(200);

  // ---- 2. clean firewall ----
  console.log("\n== synthetic firewall clean ==");
  ({ report, errors } = await loadTsf(page, path.join(ROOT, "samples/techsupport_fw-clean.tgz")));
  assert(errors.length === 0, "no JS errors on fw-clean (" + errors.join(" | ") + ")");
  assert(report.type === "Firewall", "clean type Firewall");
  assert(report.device["Hostname"] === "fw-example-clean", "clean hostname");
  const crit = report.findings.filter((f) => f.sev === "critical" && !f.suggestion).length;
  const warn = report.findings.filter((f) => f.sev === "warning" && !f.suggestion).length;
  assert(crit === 0, "clean bundle has 0 critical findings, got " + crit + " " + titles(report).join(" | "));
  assert(warn === 0, "clean bundle has 0 warnings, got " + warn + " " + titles(report).join(" | "));
  assert(report.health >= 90, "clean health is high, got " + report.health);

  // ---- 3. panorama issues ----
  console.log("\n== synthetic panorama issues ==");
  ({ report, errors } = await loadTsf(page, path.join(ROOT, "samples/techsupport_pano-issues.tgz")));
  assert(errors.length === 0, "no JS errors on pano-issues (" + errors.join(" | ") + ")");
  assert(report.type === "Panorama", "device type Panorama, got " + report.type);
  assert(/Panorama/i.test(report.device["Model"] || ""), "model Panorama");
  assert(hasTitle(report, /commit-all failed/i), "commit-all failed");
  assert(hasTitle(report, /managed device/i), "disconnected devices");
  assert(hasTitle(report, /log collector/i), "log collector");
  assert(hasTitle(report, /crash dump/i), "pano core");
  assert(hasTitle(report, /license expired/i), "logging service expired");
  assert(hasTitle(report, /disk usage high/i), "pano disk");

  // ---- 4. nested tgz ----
  console.log("\n== nested tgz ==");
  ({ report, errors } = await loadTsf(page, path.join(ROOT, "samples/techsupport_fw-issues-nested.tgz")));
  assert(errors.length === 0, "no JS errors on nested (" + errors.join(" | ") + ")");
  assert(report.device["Hostname"] === "fw-example", "nested still finds hostname");
  assert(hasTitle(report, /split brain/i), "nested still finds split brain");

  // ---- 5. thin / missing CLI ----
  console.log("\n== thin bundle (missing CLI) ==");
  ({ report, errors } = await loadTsf(page, path.join(ROOT, "samples/techsupport_fw-thin.tgz")));
  assert(errors.length === 0, "thin bundle does not crash (" + errors.join(" | ") + ")");
  assert(!report.device["PAN-OS"] || report.device["PAN-OS"] === null, "PAN-OS not claimed when CLI is missing");
  const pageNf = await page.locator("#sum").innerText();
  // With redaction on, "Not found in this bundle" should appear for missing fields
  assert(/Not found in this bundle/i.test(pageNf), "UI shows 'Not found in this bundle'");

  // ---- 6. license-gated content (synthetic mini TSFs, not committed) ----
  console.log("\n== license-gated WildFire content ==");
  const unlicensedPath = writeMiniTsf("wf-unlicensed", licenseCaseCli({
    wildfireVersion: "0",
    licenseBody: LIC_THREAT_URL,
  }));
  ({ report, errors } = await loadTsf(page, unlicensedPath));
  assert(errors.length === 0, "no JS errors on unlicensed WildFire (" + errors.join(" | ") + ")");
  assert(report.device["Hostname"] === "fw-example-lic", "unlicensed case hostname");
  const unlicWarn = (report.findings || []).filter((f) => (f.sev === "warning" || f.sev === "critical") && /security content is not installed|wildfire/i.test(f.title));
  assert(unlicWarn.length === 0, "unlicensed WildFire does not raise a content warning, got " + unlicWarn.map((f) => f.sev + ":" + f.title).join(" | "));
  assert(hasTitle(report, /not licensed:\s*WildFire/i), "unlicensed WildFire is an informational Not licensed note");
  const unlicNote = finding(report, /not licensed:\s*WildFire/i);
  assert(unlicNote && unlicNote.sev === "info", "Not licensed: WildFire is severity info");
  assert(!/GlobalProtect data file|WildFire private cloud/i.test(unlicNote.title), "unlicensed default-zero GP data file / WF private cloud are not listed");
  assert(!hasTitle(report, /not licensed:.*GlobalProtect data file/i), "no Not licensed note for default-zero GP data file");
  assert(!hasTitle(report, /not licensed:.*WildFire private cloud/i), "no Not licensed note for default-zero WF private cloud");

  const licensedMissingPath = writeMiniTsf("wf-licensed-missing", licenseCaseCli({
    wildfireVersion: "0",
    licenseBody: LIC_THREAT_URL + "\n" + LIC_WF_ACTIVE,
  }));
  ({ report, errors } = await loadTsf(page, licensedMissingPath));
  assert(errors.length === 0, "no JS errors on licensed+missing WildFire (" + errors.join(" | ") + ")");
  const missing = finding(report, /^Security content is not installed$/i);
  assert(missing && missing.sev === "warning", "licensed+missing WildFire raises a content warning");
  assert(!hasTitle(report, /not licensed:\s*WildFire/i), "licensed+missing is not described as unlicensed");
  assert(!hasTitle(report, /license expired:.*wildfire/i), "licensed+missing is not described as expired");

  const expiredPath = writeMiniTsf("wf-expired", licenseCaseCli({
    wildfireVersion: "0",
    licenseBody: LIC_THREAT_URL + "\n" + LIC_WF_EXPIRED,
  }));
  ({ report, errors } = await loadTsf(page, expiredPath));
  assert(errors.length === 0, "no JS errors on expired WildFire (" + errors.join(" | ") + ")");
  assert(hasTitle(report, /license expired:.*wildfire/i), "expired WildFire license is reported as expired");
  const expiredContent = (report.findings || []).filter((f) => /security content is not installed/i.test(f.title));
  assert(expiredContent.length === 0, "expired WildFire is not also reported as missing content, got " + expiredContent.map((f) => f.title).join(" | "));
  assert(!hasTitle(report, /not licensed:\s*WildFire/i), "expired WildFire is not described as unlicensed");

  const unknownPath = writeMiniTsf("wf-lic-unknown", licenseCaseCli({
    wildfireVersion: "0",
    licenses: false,
  }));
  ({ report, errors } = await loadTsf(page, unknownPath));
  assert(errors.length === 0, "no JS errors on missing license section (" + errors.join(" | ") + ")");
  const unknown = finding(report, /security content is not installed \(license status unknown\)/i);
  assert(unknown && unknown.sev === "info", "no license section downgrades missing WildFire content to info with license status unknown");
  assert(!report.findings.some((f) => f.sev === "warning" && /security content is not installed/i.test(f.title)), "no license section does not warn about missing content");
  assert(!hasTitle(report, /license expired:.*wildfire/i), "no license section is not reported as an expired WildFire license");

  const coreOkAncillaryZeroPath = writeMiniTsf("wf-ancillary-zero", licenseCaseCli({
    wildfireVersion: "911108",
    wildfireDate: "2026/11/08 08:00:00 PDT",
    licenseBody: LIC_THREAT_URL + "\n" + LIC_WF_ACTIVE,
  }));
  ({ report, errors } = await loadTsf(page, coreOkAncillaryZeroPath));
  assert(errors.length === 0, "no JS errors when only ancillary packages are version 0 (" + errors.join(" | ") + ")");
  assert(!hasTitle(report, /not licensed/i), "licensed core content with default-zero GP data file / WF private is not a Not licensed finding");
  assert(!hasTitle(report, /security content is not installed/i), "default-zero unlicensed ancillary packages do not warn about missing content");

  const wfPrivateLicensedPath = writeMiniTsf("wf-private-licensed-missing", licenseCaseCli({
    wildfireVersion: "911108",
    wildfireDate: "2026/11/08 08:00:00 PDT",
    extraVersions: `wf-private-version: 0
global-protect-datafile-version: 0
`,
    licenseBody: LIC_THREAT_URL + "\n" + LIC_WF_ACTIVE + `\nLicense entry:
Feature: WildFire Private Cloud
Expires: November 10, 2028
Expired: No
`,
  }));
  ({ report, errors } = await loadTsf(page, wfPrivateLicensedPath));
  assert(errors.length === 0, "no JS errors on licensed+missing WF private cloud (" + errors.join(" | ") + ")");
  const privMissing = finding(report, /^Security content is not installed$/i);
  assert(privMissing && privMissing.sev === "warning", "licensed+missing WildFire private cloud raises a content warning");

  // --- offline hygiene: CSP, Help, Dark/Help placement ---------------------------------------------------------------
  {
    console.log("\n== offline hygiene ==");
    const hp = await browser.newPage();
    const viol = [];
    const external = [];
    hp.on("console", (m) => { if (m.type() === "error" && /Content Security Policy/i.test(m.text())) viol.push(m.text()); });
    hp.on("request", (r) => { if (!/^(http:\/\/127\.0\.0\.1|blob:|data:)/.test(r.url())) external.push(r.url()); });
    await hp.goto(`http://127.0.0.1:${PORT}/pan-tsf-triage.html`, { waitUntil: "load" });
    const csp = await hp.evaluate(() => (document.querySelector('meta[http-equiv="Content-Security-Policy"]') || {}).content || "");
    assert(/default-src 'none'/.test(csp) && /connect-src 'none'/.test(csp) && /worker-src blob:/.test(csp), "strict CSP meta (no network, blob workers only)");
    const hdr = await hp.evaluate(() => [...document.querySelectorAll("header > button")].map((b) => b.id));
    assert(hdr.slice(-2).join() === "btn-help,btn-dark", "Help then Dark are the last two header buttons (" + hdr.join() + ")");
    assert(await hp.evaluate(() => document.querySelector("#help").hidden === true), "help panel starts closed");
    await hp.click("#btn-help");
    assert(await hp.evaluate(() => !document.querySelector("#help").hidden && document.querySelectorAll("#help details").length >= 4), "Help button opens the usage guide");
    await hp.click("#help-close");
    assert(await hp.evaluate(() => document.querySelector("#help").hidden === true), "Close help hides it");
    await hp.click("#btn-dark");
    assert(await hp.evaluate(() => document.body.classList.contains("dark")), "Dark toggle works");
    await hp.setInputFiles("#fi", path.join(ROOT, "samples", "techsupport_fw-clean.tgz"));
    await hp.waitForFunction(() => window.__TSF && window.__TSF.ready === true, null, { timeout: 120000 });
    assert(viol.length === 0, "no CSP violations while loading a bundle (blob worker still works): " + viol.slice(0, 1).join("|"));
    assert(external.length === 0, "no network requests outside the local page: " + external.slice(0, 1).join("|"));
    await hp.close();
  }

  await browser.close();
  server.close();
  console.log(failed ? `\n${failed} test(s) failed` : "\nAll tests passed");
  process.exit(failed ? 1 : 0);
}

main().catch((e) => {
  console.error(e);
  process.exit(2);
});
